(async function () {
  const fs = require('node:fs');
  const path = require('node:path');
  const https = require('node:https');
  const { URL } = require('node:url');
  const base = 'metaprocedures/procedures/AchiveExtraction';
  const config = JSON.parse(fs.readFileSync(path.resolve(process.cwd(), base, 'config.json'), 'utf8'));
  const remoteSource = fs.readFileSync(path.resolve(process.cwd(), base, 'apps-script-source.js'), 'utf8').trim();
  if (!/^[A-Za-z0-9._-]+$/.test(config.run_id)) throw new Error('Invalid run_id');
  if (!Array.isArray(config.archives) || !config.archives.length) throw new Error('No archives configured');
  if (!Array.isArray(config.actions) || !config.actions.length) throw new Error('No actions configured');
  const aliases = new Set();
  for (const a of config.archives) {
    if (typeof a.id !== 'string' || !a.id || typeof a.alias !== 'string' || !/^[A-Za-z0-9._-]+$/.test(a.alias) || aliases.has(a.alias)) throw new Error('Invalid archive');
    aliases.add(a.alias);
  }
  const allowed = new Set(['inspect','list_entries','extract_selected','copy_archive']);
  const actionIds = new Set();
  for (const a of config.actions) {
    if (!a.id || actionIds.has(a.id) || !allowed.has(a.type) || !aliases.has(a.archive)) throw new Error('Invalid action');
    if (a.on_error && !['continue','stop'].includes(a.on_error)) throw new Error('Invalid on_error');
    if (a.type === 'extract_selected' && (!Array.isArray(a.entries) || !a.entries.length)) throw new Error('Missing extraction entries');
    actionIds.add(a.id);
  }
  const body = JSON.stringify({sourcecode:remoteSource,arguments:{run_id:config.run_id,archives:config.archives,actions:config.actions,destination:config.destination,execution:config.execution}});
  const target = new URL(config.endpoint);
  if (target.protocol !== 'https:' || target.hostname !== 'script.google.com' || !target.pathname.endsWith('/exec')) throw new Error('Invalid Apps Script endpoint');
  const transport = await new Promise((resolve,reject)=>{
    const request = https.request(target,{method:'POST',headers:{'Content-Type':'application/json','Content-Length':Buffer.byteLength(body)},timeout:config.execution.timeout_ms || 180000},response=>{
      let sample='';
      response.on('data',chunk=>{if(sample.length<8192) sample+=chunk.toString('utf8').slice(0,8192-sample.length);});
      response.on('end',()=>resolve({status:response.statusCode,location:response.headers.location || null,body_sample:sample}));
    });
    request.on('timeout',()=>request.destroy(new Error('POST timed out')));
    request.on('error',reject);
    request.end(body);
  });
  console.log(JSON.stringify({diagnostic:'apps_script_transport',http_status:transport.status,redirect_location:transport.location,html_title:(transport.body_sample.match(/<title[^>]*>([^<]*)<\/title>/i)||[])[1]||null,google_error_hints:transport.body_sample.match(/(access denied|permission denied|sign in|authorization required|function not found|script function not found|exception|error 403|script is not available|file you have requested)/ig)?.slice(0,8)||[],body_sample:transport.body_sample.slice(0,180)}));
  if (transport.status < 200 || transport.status >= 300) throw new Error('POST did not return terminal success: HTTP '+transport.status);
  if (!transport.body_sample.trim().startsWith('{')) throw new Error('Apps Script returned non-JSON content; remote result cannot be verified');
  let remoteResult;
  try { remoteResult = JSON.parse(transport.body_sample); } catch(e) { throw new Error('Apps Script response was not valid complete JSON'); }
  if (remoteResult.error || remoteResult.status === 'FAILED') throw new Error('Apps Script error: '+JSON.stringify(remoteResult));
  if (!remoteResult.report_file_id || remoteResult.run_id !== config.run_id) throw new Error('Apps Script returned no matching Drive report locator');
  console.log(JSON.stringify({run_id:config.run_id,transport_status:transport.status,dispatch_observed:true,goal_verified:false,verification_required:'Read the run-scoped JSON report in Google Drive and compare action results with config.json.'}));
})()
